n=30
out=[[0]*n for _ in range(n)]
# Preserve outer frame on rows/cols 1..25.
for r in range(1,26):
    for c in range(1,26):
        if r in (1,25) or c in (1,25): out[r][c]=5
        else: out[r][c]=2
# inset frame, two cells in from the outer frame
for r in range(3,24):
    for c in range(3,24):
        if r in (3,23) or c in (3,23): out[r][c]=5
print('\n'.join('['+','.join(map(str,row))+'],' for row in out))
